{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.plaeto_unicommerce_fact_items as SELECT null AS customer_id, shipping_address_pincode AS pincode, channel_name AS marketplace, channel_name AS source, display_order_code AS order_id, display_order_code AS reference_code, Notification_Mobile AS phone, Billing_Address_Name AS name, cast(null AS string) AS email, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(updated, \'\')))) AS SHIPPING_LAST_UPDATE_DATE, item_sku_code AS sku, Seller_SKU_Code AS Marketplace_sku, CASE WHEN REGEXP_CONTAINS(channel_product_id, r\'^\d+-\d+$\') THEN SPLIT(channel_product_id, \'-\')[OFFSET(0)] ELSE channel_product_id END AS product_id, CASE WHEN REGEXP_CONTAINS(channel_product_id, r\'^\d+-\d+$\') THEN SPLIT(channel_product_id, \'-\')[OFFSET(1)] ELSE NULL END AS variant_id, item_type_name AS product_name, currency, coalesce(shipping_address_city, Billing_Address_City) city, coalesce(shipping_address_state, Billing_Address_state) state, sale_order_status AS order_status, invoice_code, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(invoice_created, \'\')))) AS invoiceDate, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(Order_Date_as_dd_mm_yyyy_hh_MM_ss, \'\')))) AS Order_Date, SAFE_CAST(Shipping_Charges AS FLOAT64) AS shipping_price, 1 AS suborder_quantity, SAFE_CAST(discount AS FLOAT64) AS discount, SAFE_CAST(tax_value AS FLOAT64) AS tax, SAFE_CAST(selling_price AS FLOAT64) AS selling_price, Shipping_Package_Code AS shippingPackageCode, Shipping_Package_Status_Code AS shippingPackageStatus, Sale_Order_Item_Code AS SaleOrderItemCode, Sale_Order_Item_Code AS Sales_Order_Item_ID, Tracking_Number AS AWB, Facility AS Warehouse_Name, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Mode, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Method, Shipping_Courier AS Courier, Shipping_Courier_Status AS shipping_status, 1 AS shippedQuantity, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(Dispatch_Date, \'\')))) AS Dispatch_Date, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(Delivery_Time, \'\')))) AS Delivered_Date, DATETIME(FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', NULLIF(return_date, \'\')))) AS return_date, return_remarks, Reverse_Pickup_Reason, CASE WHEN return_date IS NOT NULL AND TRIM(CAST(return_date AS STRING)) <> \'\' AND LOWER(TRIM(CAST(return_date AS STRING))) <> \'null\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN return_date IS NOT NULL AND TRIM(CAST(return_date AS STRING)) <> \'\' AND LOWER(TRIM(CAST(return_date AS STRING))) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN return_date IS NOT NULL AND TRIM(CAST(return_date AS STRING)) <> \'\' AND LOWER(TRIM(CAST(return_date AS STRING))) <> \'null\' THEN CAST(selling_price AS FLOAT64) ELSE 0 END AS return_sales, CASE WHEN lower(sale_order_status) LIKE \'%cancel%\' OR lower(shipping_courier_status) LIKE \'%cancel%\' THEN 1 ELSE 0 END AS cancelled_quantity, cast(null AS string) AS new_customer_flag, cast(null AS string) AS acquisition_product, null AS days_in_shipment, null AS acquisition_date, p.SKUCODE AS SKU_CODE, upper(p.PRODUCT_name) AS PRODUCT_NAME_Final, Upper(p.CATEGORY) AS Product_Category, Upper(p.category_gender) AS Product_Category_Gender, Upper(p.skucode) AS commonsku, Upper(p.colour_code) AS colour_code, Upper(p.product_code) AS product_code, Upper(p.style_name) AS style_name, Upper(p.sub_style_name) AS sub_style_name, upper(p.size) AS size, upper(p.size_band) AS size_band, upper(p.Colour) AS Colour, upper(p.Colour_2) AS Colour_2 from `maplemonk.Unicommerce_get_sale_orders` fi left join (select * from ( select master_sku as skucode, master_sku commonsku, colour_code, style_code, product_code, category_gender, style_name, sub_style_name, product_name, outsole_colour, category, size, size_band, Colour, Colour_2, fob, mrp, row_number() over (partition by lower(replace(master_sku,\' \',\'\')) order by 1) rw from plaeup-wh.maplemonk.Final_SKU_master ) where rw = 1 ) p on lower(replace(fi.item_sku_code,\' \',\'\')) = lower(replace(p.skucode,\' \',\'\')) qualify row_number() over (partition by display_order_code,Sale_Order_Item_Code order by FORMAT_DATETIME(\'%Y-%m-%dT%H:%M:%S\', PARSE_DATETIME(\'%Y-%m-%d %H:%M:%S\', updated)) desc) = 1 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
